import React from 'react';
import { motion } from 'framer-motion';
import { useInView } from 'react-intersection-observer';
import { Github, ExternalLink, TrendingUp, Sprout, Wind, Heart, ShoppingBag } from 'lucide-react';

const Projects = () => {
  const [ref, inView] = useInView({
    triggerOnce: true,
    threshold: 0.1,
  });

  const projects = [
    {
      icon: TrendingUp,
      title: 'Customer Churn Prediction',
      problem: 'Developed a predictive model to identify customers at risk of leaving, helping businesses implement proactive retention strategies.',
      techStack: ['Python', 'Scikit-learn', 'Pandas', 'XGBoost'],
      insights: 'Achieved 92% accuracy with feature engineering and ensemble methods',
      github: 'https://github.com/bharath/churn-prediction',
      demo: 'https://churn-prediction-demo.vercel.app',
      color: 'from-blue-500 to-cyan-500',
    },
    {
      icon: Sprout,
      title: 'AI Smart Farming System',
      problem: 'Created an intelligent system to optimize crop management through IoT sensors and machine learning predictions.',
      techStack: ['Python', 'TensorFlow', 'IoT', 'Flask'],
      insights: 'Improved crop yield by 25% and reduced water usage by 30%',
      github: 'https://github.com/bharath/smart-farming',
      demo: 'https://smart-farming-demo.vercel.app',
      color: 'from-green-500 to-teal-500',
    },
    {
      icon: Wind,
      title: 'Air Quality Monitoring System',
      problem: 'Built a real-time air quality monitoring platform with predictive analytics for pollution forecasting.',
      techStack: ['Python', 'React.js', 'API Integration', 'Time Series'],
      insights: 'Integrated data from 50+ sensors with 95% prediction accuracy',
      github: 'https://github.com/bharath/air-quality-monitor',
      demo: 'https://air-quality-demo.vercel.app',
      color: 'from-purple-500 to-pink-500',
    },
    {
      icon: Heart,
      title: 'Healthcare Analytics Platform',
      problem: 'Developed a comprehensive analytics platform for healthcare data visualization and patient outcome prediction.',
      techStack: ['Python', 'Power BI', 'SQL', 'Machine Learning'],
      insights: 'Reduced readmission rates by 15% through predictive insights',
      github: 'https://github.com/bharath/healthcare-analytics',
      demo: 'https://healthcare-analytics-demo.vercel.app',
      color: 'from-red-500 to-orange-500',
    },
    {
      icon: ShoppingBag,
      title: 'Smart Shopping Assistant',
      problem: 'Created an AI-powered shopping recommendation system using collaborative filtering and NLP.',
      techStack: ['Python', 'NLP', 'React.js', 'MongoDB'],
      insights: 'Increased user engagement by 40% with personalized recommendations',
      github: 'https://github.com/bharath/smart-shopping',
      demo: 'https://smart-shopping-demo.vercel.app',
      color: 'from-indigo-500 to-purple-500',
    },
  ];

  const containerVariants = {
    hidden: { opacity: 0 },
    visible: {
      opacity: 1,
      transition: {
        staggerChildren: 0.2,
      },
    },
  };

  const itemVariants = {
    hidden: { opacity: 0, translateY: 20 },
    visible: {
      opacity: 1,
      translateY: 0,
      transition: {
        duration: 0.5,
      },
    },
  };

  return (
    <section id="projects" className="py-20 relative">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <motion.div
          ref={ref}
          initial="hidden"
          animate={inView ? 'visible' : 'hidden'}
          variants={containerVariants}
        >
          {/* Section Header */}
          <motion.div variants={itemVariants} className="text-center mb-16">
            <h2 className="section-title">Featured Projects</h2>
            <p className="section-subtitle max-w-2xl mx-auto">
              Showcasing innovative solutions that solve real-world problems
            </p>
          </motion.div>

          {/* Projects Grid */}
          <div className="grid md:grid-cols-2 gap-8">
            {projects.map((project) => (
              <motion.div
                key={project.title}
                variants={itemVariants}
                className="glass-card p-6 hover:scale-105 transition-transform duration-300 group"
              >
                {/* Project Header */}
                <div className="flex items-start justify-between mb-4">
                  <div className={`p-3 rounded-lg bg-gradient-to-r ${project.color}`}>
                    <project.icon className="w-8 h-8 text-white" />
                  </div>
                  <div className="flex gap-2">
                    <a
                      href={project.github}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="p-2 rounded-lg bg-dark-800 hover:bg-dark-700 transition-colors"
                      aria-label="View on GitHub"
                    >
                      <Github className="w-5 h-5 text-gray-400 hover:text-white" />
                    </a>
                    <a
                      href={project.demo}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="p-2 rounded-lg bg-dark-800 hover:bg-dark-700 transition-colors"
                      aria-label="View Live Demo"
                    >
                      <ExternalLink className="w-5 h-5 text-gray-400 hover:text-white" />
                    </a>
                  </div>
                </div>

                {/* Project Content */}
                <h3 className="text-xl font-semibold mb-3 group-hover:text-accent-400 transition-colors">
                  {project.title}
                </h3>

                <p className="text-gray-400 mb-4 text-sm leading-relaxed">
                  {project.problem}
                </p>

                {/* Tech Stack */}
                <div className="flex flex-wrap gap-2 mb-4">
                  {project.techStack.map((tech) => (
                    <span
                      key={tech}
                      className="px-3 py-1 text-xs rounded-full bg-dark-800 text-gray-300 border border-white/10"
                    >
                      {tech}
                    </span>
                  ))}
                </div>

                {/* Key Insights */}
                <div className="p-3 rounded-lg bg-accent-400/5 border border-accent-400/10">
                  <p className="text-sm text-accent-400">
                    <span className="font-semibold">Key Result:</span> {project.insights}
                  </p>
                </div>
              </motion.div>
            ))}
          </div>

          {/* Call to Action */}
          <motion.div variants={itemVariants} className="mt-12 text-center">
            <a
              href="https://github.com/bharath"
              target="_blank"
              rel="noopener noreferrer"
              className="btn-primary inline-flex items-center gap-2"
            >
              <Github className="w-5 h-5" />
              View All Projects on GitHub
            </a>
          </motion.div>
        </motion.div>
      </div>
    </section>
  );
};

export default Projects;
